#include <algorithm>
#include <cstddef>
#include <cstdint>
static std::int64_t rounded_shift(std::int64_t x,int shift){const std::int64_t d=std::int64_t(1)<<shift;return x>=0?x/d:-((-x+d-1)/d);}
extern "C" std::int64_t depthconv(const std::int64_t*v,std::size_t n,std::uint8_t*out,std::size_t cap){constexpr std::size_t maxc=8;if(!v||n<1||n>1+11*maxc)return -1;const auto cc=v[0];if(cc<1||cc>8||n!=1+11*std::size_t(cc))return -1;const auto c=std::size_t(cc);for(std::size_t i=1;i<1+8*c;i++)if(v[i]<-128||v[i]>127)return -1;for(std::size_t i=1+8*c;i<1+9*c;i++)if(v[i]<-1000000||v[i]>1000000)return -1;for(std::size_t i=1+9*c;i<1+10*c;i++)if(v[i]<0||v[i]>2147483647)return -1;for(std::size_t i=1+10*c;i<n;i++)if(v[i]<-8||v[i]>0)return -1;if(!out||cap<c)return -2;for(std::size_t ch=0;ch<c;ch++){std::int32_t acc=0;for(std::size_t y=0;y<4;y++)acc+=std::int32_t(v[1+4*c+y*c+ch])*std::int32_t(v[1+y*c+ch]+128);acc+=std::int32_t(v[1+8*c+ch]);const int shift=int(31-v[1+10*c+ch]);const auto round=std::int64_t(1)<<(shift-1);auto scaled=rounded_shift(std::int64_t(acc)*v[1+9*c+ch]+round,shift);scaled=std::clamp<std::int64_t>(scaled,-128,127);out[ch]=static_cast<std::uint8_t>(static_cast<std::int8_t>(scaled));}return std::int64_t(c);}
